-- The demo account identity guard on auth.users. The trigger exists only when
-- the migration role may create triggers on auth.users; when it does not, each
-- check is skipped with that reason and the demo account is regenerated by hand.

begin;

select plan(6);

-- The demo user, with the id the trigger protects, and an unrelated user.
insert into auth.users (id, instance_id, aud, role, email, encrypted_password, phone)
values
  ('94f56c85-36dd-4feb-89ae-92254754fc93', '00000000-0000-0000-0000-000000000000',
   'authenticated', 'authenticated', 'demo-identity-test@example.com', 'hash-1', '+10000000001'),
  ('94f56c85-36dd-4feb-89ae-92254754fc94', '00000000-0000-0000-0000-000000000000',
   'authenticated', 'authenticated', 'other-identity-test@example.com', 'hash-2', '+10000000002');

select case
  when exists (select 1 from pg_trigger where tgname = 'trg_demo_identity_guard')
    then throws_ok(
      $$ update auth.users set email = 'changed@example.com'
          where id = '94f56c85-36dd-4feb-89ae-92254754fc93' $$,
      'TX003', 'the identity of the demo account cannot be changed',
      'the demo e-mail cannot be changed')
  else skip('the platform does not allow a trigger on auth.users', 1)
end;

select case
  when exists (select 1 from pg_trigger where tgname = 'trg_demo_identity_guard')
    then throws_ok(
      $$ update auth.users set encrypted_password = 'hash-changed'
          where id = '94f56c85-36dd-4feb-89ae-92254754fc93' $$,
      'TX003', 'the identity of the demo account cannot be changed',
      'the demo password cannot be changed')
  else skip('the platform does not allow a trigger on auth.users', 1)
end;

select case
  when exists (select 1 from pg_trigger where tgname = 'trg_demo_identity_guard')
    then throws_ok(
      $$ update auth.users set phone = '+10000000099'
          where id = '94f56c85-36dd-4feb-89ae-92254754fc93' $$,
      'TX003', 'the identity of the demo account cannot be changed',
      'the demo phone cannot be changed')
  else skip('the platform does not allow a trigger on auth.users', 1)
end;

-- An update that rewrites the same values, as the auth service does on sign-in.
select case
  when exists (select 1 from pg_trigger where tgname = 'trg_demo_identity_guard')
    then lives_ok(
      $$ update auth.users
            set email = 'demo-identity-test@example.com',
                encrypted_password = 'hash-1',
                phone = '+10000000001',
                last_sign_in_at = now()
          where id = '94f56c85-36dd-4feb-89ae-92254754fc93' $$,
      'an update that keeps the same identity values is accepted')
  else skip('the platform does not allow a trigger on auth.users', 1)
end;

select case
  when exists (select 1 from pg_trigger where tgname = 'trg_demo_identity_guard')
    then lives_ok(
      $$ update auth.users set last_sign_in_at = now()
          where id = '94f56c85-36dd-4feb-89ae-92254754fc93' $$,
      'a change of another column of the demo user is accepted')
  else skip('the platform does not allow a trigger on auth.users', 1)
end;

select case
  when exists (select 1 from pg_trigger where tgname = 'trg_demo_identity_guard')
    then lives_ok(
      $$ update auth.users set email = 'other-changed@example.com'
          where id = '94f56c85-36dd-4feb-89ae-92254754fc94' $$,
      'the identity of any other user can change')
  else skip('the platform does not allow a trigger on auth.users', 1)
end;

select * from finish();

rollback;
